css:
.voucher{font-family:Arial,Helvetica,sans-serif;color:#000;font-size:12.5px}
.voucher .mh{text-align:center;margin-bottom:14px}
.voucher .mh .nm{font-family:"Oswald",Arial,sans-serif;font-weight:700;font-size:27px;line-height:1.05}
.voucher .mh .pl{font-family:"Oswald",Arial,sans-serif;font-weight:500;font-size:14px}
.voucher .fields{display:flex;flex-direction:column;gap:7px;margin-bottom:12px}
.voucher .fr{display:flex;align-items:flex-end;gap:7px}
.voucher .fl{font-weight:700;white-space:nowrap;flex:none}
.voucher .fv{flex:1;border-bottom:1px solid #000;min-height:19px;padding:0 3px 1px}
.voucher .fv.grow2{flex:2}
.voucher table.vt{border-collapse:collapse;width:100%;table-layout:fixed;margin-bottom:14px}
.voucher table.vt th,.voucher table.vt td{border:1px solid #000;padding:6px 8px;vertical-align:top}
.voucher table.vt th{text-align:center;font-weight:700;font-size:12px}
.voucher .c-sn{width:52px;text-align:center}
.voucher .c-amt{width:96px;text-align:right}
.voucher .vt .filler td{height:20px}
.voucher .vt .wordrow td{font-weight:700}
.voucher .vt .wordrow .w{font-weight:400;padding-left:6px}
.voucher .vt .grand{font-weight:700;font-size:14px}
.voucher .sigs{display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px;margin-top:32px}
.voucher .sigs.two{grid-template-columns:1fr 1fr;gap:40px}
.voucher .sig{text-align:center}
.voucher .sig .nm{font-size:12.5px;min-height:17px;border-bottom:1px solid #999;padding-bottom:2px;margin-bottom:4px}
.voucher .sig .lb{font-weight:700;font-size:11px}
.voucher .sig:first-child .lb{text-align:left}
.voucher .sig:last-child .lb{text-align:right}
